scripts.何梅对话.txt:
// 何梅对话

	If ($Event == 180) @Event180;
	If ($Event == 190) @Event190;
	If ($Event >> 190) @Eventmorethan190;

@Event180:
	Say("何梅：这里就是我的家，爹爹在大厅，我们去见他吧。", 66);
	Say("独孤剑：好的。", 2);
	Return;
	
@Event190:
	If ($Talkhejiayahuan == 0) @Talk0;
	If ($Talkhejiayahuan == 1) @Talk1;
@Talk0:
	Say("何梅：公子，你……真的要走吗？",66);
	Say("独孤剑：何姑娘，你才貌俱佳，善良温柔，将来定会找到一个比我强上百倍的如意郎君，独孤剑乃是漂泊江湖的一介莽夫，姑娘跟着我只会受苦，独孤剑怎能耽误姑娘一生？", 1);
	Say("何梅：我并不怕吃苦！", 66);
	Say("独孤剑：……", 1);
	Say("何梅：其实，公子之所以不愿意答应我爹的提亲，是因为那位……张姑娘，对吗？", 66);
	Say("独孤剑：何姑娘，我……", 1);
	Say("何梅：公子不必多说，何梅明白了。何梅不怪公子，只怪造化弄人，希望来世上天能够成全这段因缘……", 66);
	Say("独孤剑：何姑娘，对不起。", 1);
	Say("何梅：公子不必内疚，何梅会一辈子记住公子的救命之恩，愿你和张姑娘有情人终成眷属！", 66);
	Say("独孤剑：多谢！在下告辞了。", 2);
	Say("何梅：公子多保重！", 66);
	Assign($Talkhejiayahuan, 1);
	Return;	
@Talk1:
	Say("何梅：<enter>零零露珠一点，波影，满池塘；<enter>残梅冷剑两相乱，肠断，泪也凉。", 66);
	Say("公子，珍重！", 66);
	Return;	
	
@Eventmorethan190:	
	Say("何梅：啊！是独孤公子！", 66);
	Say("独孤剑：姑娘一向可好？", 1);
	Say("何梅：我很好！公子和张姑娘可好……", 66);
	Say("独孤剑：有劳姑娘挂记。", 1);
	Return;

scripts.何员外对话.txt:
//与何员外的对话

	If ($Event << 180) @Eventlessthan180;
	
	Say("何员外：多谢独孤公子相救小女，唉，只可惜这么好的女婿……", 0);
	Return;

@Eventlessthan180:
	Say("何员外：我的独生女儿小梅前天被贼人抓走了，谁要是能把她找回来，我就招他为婿，全部家产都给他……", 0);
	Return;

scripts.贾老实对话.txt:
// 与贾老实的同伴对话

	If($Event == 120) @Event120;
	Return;
	
@Event120:
	If($Talkmap026jia == 0) @Talk0;
	If($Talkmap026jia == 1) @Talk1;
	If($Talkmap026jia == 2) @Talk2;
	Return;
	
@Talk0:
	Say("贾老实：京城是个花花世界，如果不是因为金兵南下，这里以前更热闹。", 207);
	Assign($Talkmap026jia, 1);
	Return;	
@Talk1:
	Say("贾老实：人生在世，不就是图个吃喝玩乐，老弟，你说呢？", 207);
	Say("独孤剑：如果只顾自己享乐，而置国家安危于不顾，有朝一日金兵南侵，攻破城池，覆巢之下，安有完卵？", 1);
	Say("贾老实：哪里管得了那许多！", 207);
	Say("独孤剑：人人都像你这样想，大宋迟早要亡国。", 1);
	Assign($Talkmap026jia, 2);
	Return;
@Talk2:
	Say("贾老实：我最关心的就是赚钱，别的我可不想管。", 207);
	Say("独孤剑：……", 1);
	Return;

scripts.何家丫环对话1.txt:
