traps.Trap02.txt:
// 救回何梅以后见何员外

	If ($Event == 180) @Event180;
	Return;
		
@Event180:
	StopMusic();
	PlayMusic("春潮.mp3");
	SetNpcKind("何梅", 0);
	NpcGoto("何梅", 9, 32);
	SetNpcDir("何梅", 3);
	PlayerGoto(9, 34);
	SetPlayerDir(4);
	
	Say("何梅：爹！……呜呜……", 66);
	Say("何员外：小梅，真的是你吗？我不是在做梦吧？爹还以为再也见不到你了。", 0);
	Say("何梅：爹……呜呜……", 66);
	Say("何员外：回来就好，回来就好，女儿，他们……没有把你怎样吧？", 0);
	Say("何梅：没有。爹，是这位独孤公子救了女儿，如果不是他，恐怕女儿再也见不到爹了！", 66);
	
	NpcGoto("何员外", 8, 33);
	SetNpcDir("何员外", 7);
	SetPlayerDir(3);
	SetNpcDir("何梅", 1);
	Say("何员外：公子，你是我何某全家的救命恩人哪。", 0);
	Say("独孤剑：员外言重了。救人于危难是习武之人的本分，何足挂齿！", 2);
	Say("何员外：公子一表人材，又身手不凡，真是我何家之福啊。", 0);
	Say("独孤剑：这……从何说起。", 8);
	Say("何员外：公子放心。老夫既有承诺，就决不食言。公子救回小女，那就是我何家的好女婿，何某虽然无能，但区区万贯家资，当可尽独孤公子差使。", 0);
	Say("独孤剑：这……员外，你误会了……", 8);
	Say("何梅：爹！……", 66);
	NpcGoto("何梅", 10, 31);
	NpcGoto("何梅", 10, 25);
	PlayerGoto(9, 33);
	NpcGoto("何梅", 11, 17);
	SetPlayerDir(5);
	SetNpcDir("何梅", 4);
	Say("独孤剑：何姑娘，我……", 8);
	SetPlayerDir(2);
	//SetNpcDir("何员外", 7);
	//Watch("独孤剑", "何员外", 0);
	Say("何员外：哈哈哈哈，公子别见外，小女就是这样——被说中心事，就害羞了。公子也宜尽速禀明堂上，由老夫择个良辰吉日，和小女完婚如何？", 0);
		
	Choose("独孤剑：答不答应呢？","A 应允","B 谢绝", $Choosemarry);
	If ($Choosemarry == 0) @Choose0;
	If ($Choosemarry == 1) @Choose1;	
	
@Choose0:
	Say("独孤剑：这个……", 4);
	Say("何员外：公子还有什么犹豫的，难道嫌弃小女高攀不上？", 0);
	Say("独孤剑：如此，就多谢岳父大人成全。", 4);
	Say("何员外：太好了！老夫今日要和贤婿痛饮，不醉不休，哈哈哈！", 0);
	Say("何员外：小梅，快来见过你相公！", 0);
	Memo("独孤剑前往何员外家，何员外因为感谢独孤剑救了他女儿，所以提出招独孤剑为婿。");
	Memo("面对温柔可人的何梅，独孤剑欣然答应，两人结为夫妻，一年后生下一子，取名为独孤岛，以纪念二人在岛上的相遇。");
	FadeOut();
	StopMusic();
	Say("独孤剑与何梅结为夫妻以后，生活富足美满，一年之后生下一子，取名为独孤岛，以纪念二人在碧霞岛上的奇遇。");
	PlayMovie("over.avi", 0, 0, 0);
	ReturnToTitle();
	Return;
	
@Choose1:
	Say("独孤剑：多谢老人家的美意，无奈在下积父仇师仇于一身，怎敢不去报仇雪恨而在此贪享欢娱？还请老人家见谅。", 1);
	Say("何员外：原来如此……公子既深明大义，老夫也不便勉强，这婚约不提也罢。", 0);
	MoveScreen(4, 100, 2);
	Say("何梅：他竟然不愿意……公子啊公子，如果你我是无缘之人，你又何必救我？", 66);
	SetPlayerScn();
	Say("何员外：公子大恩无以为报，如果老夫这里有什么看的上的，公子请随便取用。", 0);
	Say("独孤剑：多谢员外美意，在下告辞了。", 2);
	Assign($Event, 190);
	SetMapTrap(1, "Trap01.txt");
	SetMapTrap(2, "");
	Memo("独孤剑前往何员外家，何员外因为感谢独孤剑救了他女儿，所以提出招独孤剑为婿。");
	Memo("壮志未酬，何以为家？独孤剑拒绝了何员外的好意。");
	Return;
